<?php

declare(strict_types=1);

namespace App\Actions\Jarvis;

use App\Enums\JarvisConnectionStatus;
use App\Models\JarvisConnection;
use App\Models\User;
use App\Services\Composio\ComposioClient;

/**
 * Start a one-step connection to a product such as Gmail, Drive, or Notion.
 *
 * A connect link is generated by Composio and stored on the connection so the
 * UI can send the user straight to the provider's consent screen.
 */
final class ConnectJarvisToolkit
{
    public function __construct(
        private readonly ComposioClient $composio,
    ) {}

    public function __invoke(User $user, string $toolkit, ?string $callbackUrl = null): JarvisConnection
    {
        $toolkit = mb_strtolower($toolkit);
        $definition = $this->composio->findToolkit($toolkit);
        $link = $this->composio->connectLink($user, $toolkit, $callbackUrl);

        /** @var JarvisConnection $connection */
        $connection = JarvisConnection::query()->updateOrCreate(
            [
                'user_id' => $user->getKey(),
                'toolkit' => $toolkit,
            ],
            [
                'name' => $definition['name'] ?? $toolkit,
                'status' => JarvisConnectionStatus::Pending,
                'auth_config_id' => $link['auth_config_id'],
                'connected_account_id' => $link['connected_account_id'],
                'meta' => [
                    'redirect_url' => $link['redirect_url'],
                    'requested_at' => now()->toIso8601String(),
                ],
            ],
        );

        return $connection;
    }
}
